interface Lanter_DriverInterface{public function connect(array$connection):void;public function listTables():array;public function describeTable(string$table):array;public function fetchRows(string$table,int$limit,int$offset,?string$search=null):array;public function countRows(string$table,?string$search=null):int;public function findRow(string$table,string$primaryKey,mixed$primaryValue):?array;public function insertRow(string$table,array$data):void;public function updateRow(string$table,string$primaryKey,mixed$primaryValue,array$data):void;public function deleteRow(string$table,string$primaryKey,mixed$primaryValue):void;public function runQuery(string$sql):array;}class Lanter_SqliteDriver implements Lanter_DriverInterface{private PDO$pdo;public function connect(array$connection):void{$path=$connection['path']??$connection['database']??':memory:';$this->pdo=new PDO('sqlite:'.$path);$this->pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$this->pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);}public function listTables():array{$stmt=$this->pdo->query("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name");return array_column($stmt->fetchAll(),'name');}public function describeTable(string$table):array{$stmt=$this->pdo->prepare('PRAGMA table_info('.$this->quoteIdentifier($table).')');$stmt->execute();$columns=[];foreach($stmt->fetchAll()as$row){$columns[]=['name'=>$row['name'],'type'=>$row['type'],'nullable'=>$row['notnull']===0,'default'=>$row['dflt_value'],'key'=>$row['pk']>0?'PRI':'',];}return$columns;}public function fetchRows(string$table,int$limit,int$offset,?string$search=null):array{[$where,$params]=$this->buildSearchClause($table,$search);$sql=sprintf('SELECT * FROM %s%s LIMIT %d OFFSET %d',$this->quoteIdentifier($table),$where,$limit,$offset);$stmt=$this->pdo->prepare($sql);$stmt->execute($params);return$stmt->fetchAll();}public function countRows(string$table,?string$search=null):int{[$where,$params]=$this->buildSearchClause($table,$search);$stmt=$this->pdo->prepare('SELECT COUNT(*) AS total FROM '.$this->quoteIdentifier($table).$where);$stmt->execute($params);return(int)$stmt->fetch()['total'];}private function buildSearchClause(string$table,?string$search):array{if($search===null||$search===''){return['',[]];}$columns=array_column($this->describeTable($table),'name');if($columns===[]){return['',[]];}$conditions=array_map(fn(string$column):string=>'CAST('.$this->quoteIdentifier($column).' AS TEXT) LIKE :__search',$columns);return[' WHERE '.implode(' OR ',$conditions),['__search'=>'%'.$search.'%']];}public function findRow(string$table,string$primaryKey,mixed$primaryValue):?array{$sql=sprintf('SELECT * FROM %s WHERE %s = :__pk LIMIT 1',$this->quoteIdentifier($table),$this->quoteIdentifier($primaryKey));$stmt=$this->pdo->prepare($sql);$stmt->execute(['__pk'=>$primaryValue]);$row=$stmt->fetch();return$row===false?null:$row;}public function insertRow(string$table,array$data):void{$columns=array_keys($data);$placeholders=array_map(static fn(string$column):string=>':'.$column,$columns);$sql=sprintf('INSERT INTO %s (%s) VALUES (%s)',$this->quoteIdentifier($table),implode(', ',array_map($this->quoteIdentifier(...),$columns)),implode(', ',$placeholders));$stmt=$this->pdo->prepare($sql);$stmt->execute($data);}public function updateRow(string$table,string$primaryKey,mixed$primaryValue,array$data):void{$assignments=implode(', ',array_map(fn(string$column):string=>$this->quoteIdentifier($column).' = :'.$column,array_keys($data)));$sql=sprintf('UPDATE %s SET %s WHERE %s = :__pk',$this->quoteIdentifier($table),$assignments,$this->quoteIdentifier($primaryKey));$stmt=$this->pdo->prepare($sql);$stmt->execute([...$data,'__pk'=>$primaryValue]);}public function deleteRow(string$table,string$primaryKey,mixed$primaryValue):void{$sql=sprintf('DELETE FROM %s WHERE %s = :__pk',$this->quoteIdentifier($table),$this->quoteIdentifier($primaryKey));$stmt=$this->pdo->prepare($sql);$stmt->execute(['__pk'=>$primaryValue]);}public function runQuery(string$sql):array{$stmt=$this->pdo->query($sql);if($stmt===false){return['columns'=>[],'rows'=>[],'affected'=>0];}if($stmt->columnCount()===0){return['columns'=>[],'rows'=>[],'affected'=>$stmt->rowCount()];}$rows=$stmt->fetchAll();$columns=$rows===[]?[]:array_keys($rows[0]);return['columns'=>$columns,'rows'=>$rows,'affected'=>count($rows)];}private function quoteIdentifier(string$identifier):string{return'"'.str_replace('"','""',$identifier).'"';}}class Lanter_MysqlDriver implements Lanter_DriverInterface{private PDO$pdo;private string$database;public function connect(array$connection):void{$host=$connection['host']??'127.0.0.1';$port=$connection['port']??3306;$this->database=$connection['database']??'';$dsn=sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$host,$port,$this->database);$this->pdo=new PDO($dsn,$connection['user']??'',$connection['password']??'');$this->pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$this->pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);}public function listTables():array{$stmt=$this->pdo->query('SHOW TABLES');return array_column($stmt->fetchAll(PDO::FETCH_NUM),0);}public function describeTable(string$table):array{$stmt=$this->pdo->prepare('DESCRIBE '.$this->quoteIdentifier($table));$stmt->execute();$columns=[];foreach($stmt->fetchAll()as$row){$columns[]=['name'=>$row['Field'],'type'=>$row['Type'],'nullable'=>$row['Null']==='YES','default'=>$row['Default'],'key'=>$row['Key'],];}return$columns;}public function fetchRows(string$table,int$limit,int$offset,?string$search=null):array{[$where,$params]=$this->buildSearchClause($table,$search);$sql=sprintf('SELECT * FROM %s%s LIMIT %d OFFSET %d',$this->quoteIdentifier($table),$where,$limit,$offset);$stmt=$this->pdo->prepare($sql);$stmt->execute($params);return$stmt->fetchAll();}public function countRows(string$table,?string$search=null):int{[$where,$params]=$this->buildSearchClause($table,$search);$stmt=$this->pdo->prepare('SELECT COUNT(*) AS total FROM '.$this->quoteIdentifier($table).$where);$stmt->execute($params);return(int)$stmt->fetch()['total'];}private function buildSearchClause(string$table,?string$search):array{if($search===null||$search===''){return['',[]];}$columns=array_column($this->describeTable($table),'name');if($columns===[]){return['',[]];}$conditions=array_map(fn(string$column):string=>'CAST('.$this->quoteIdentifier($column).' AS CHAR) LIKE :__search',$columns);return[' WHERE '.implode(' OR ',$conditions),['__search'=>'%'.$search.'%']];}public function findRow(string$table,string$primaryKey,mixed$primaryValue):?array{$sql=sprintf('SELECT * FROM %s WHERE %s = :__pk LIMIT 1',$this->quoteIdentifier($table),$this->quoteIdentifier($primaryKey));$stmt=$this->pdo->prepare($sql);$stmt->execute(['__pk'=>$primaryValue]);$row=$stmt->fetch();return$row===false?null:$row;}public function insertRow(string$table,array$data):void{$columns=array_keys($data);$placeholders=array_map(static fn(string$column):string=>':'.$column,$columns);$sql=sprintf('INSERT INTO %s (%s) VALUES (%s)',$this->quoteIdentifier($table),implode(', ',array_map($this->quoteIdentifier(...),$columns)),implode(', ',$placeholders));$stmt=$this->pdo->prepare($sql);$stmt->execute($data);}public function updateRow(string$table,string$primaryKey,mixed$primaryValue,array$data):void{$assignments=implode(', ',array_map(fn(string$column):string=>$this->quoteIdentifier($column).' = :'.$column,array_keys($data)));$sql=sprintf('UPDATE %s SET %s WHERE %s = :__pk',$this->quoteIdentifier($table),$assignments,$this->quoteIdentifier($primaryKey));$stmt=$this->pdo->prepare($sql);$stmt->execute([...$data,'__pk'=>$primaryValue]);}public function deleteRow(string$table,string$primaryKey,mixed$primaryValue):void{$sql=sprintf('DELETE FROM %s WHERE %s = :__pk',$this->quoteIdentifier($table),$this->quoteIdentifier($primaryKey));$stmt=$this->pdo->prepare($sql);$stmt->execute(['__pk'=>$primaryValue]);}public function runQuery(string$sql):array{$stmt=$this->pdo->query($sql);if($stmt===false){return['columns'=>[],'rows'=>[],'affected'=>0];}if($stmt->columnCount()===0){return['columns'=>[],'rows'=>[],'affected'=>$stmt->rowCount()];}$rows=$stmt->fetchAll();$columns=$rows===[]?[]:array_keys($rows[0]);return['columns'=>$columns,'rows'=>$rows,'affected'=>count($rows)];}private function quoteIdentifier(string$identifier):string{return'`'.str_replace('`','``',$identifier).'`';}}final class Lanter_Config{private array$data;private function __construct(array$data){$this->data=$data;}public static function resolve():self{$defaults=['auth'=>['mode'=>'login','delegate'=>null,],'connections'=>[],'allow_ui_connections'=>true,'data_file'=>__DIR__.'/lanter_data.sqlite',];$external=defined('LANTER_CONFIG')?LANTER_CONFIG:[];return new self(array_replace_recursive($defaults,$external));}public function authMode():string{return$this->data['auth']['mode'];}public function authDelegate():?callable{return$this->data['auth']['delegate'];}public function fixedConnections():array{return$this->data['connections'];}public function allowUiConnections():bool{return$this->data['allow_ui_connections'];}public function dataFile():string{return$this->data['data_file'];}}final class Lanter_Auth{public function __construct(private Lanter_Config$config){}public function resolveConnection():?array{return match($this->config->authMode()){'none'=>$this->resolveNoneMode(),'delegate'=>$this->resolveDelegateMode(),default=>$this->resolveLoginMode(),};}public function logout():void{unset($_SESSION['lanter_connection']);}private function resolveNoneMode():?array{if(isset($_SESSION['lanter_connection'])){return$_SESSION['lanter_connection'];}$connections=$this->config->fixedConnections();if($connections===[]){return null;}if(isset($_GET['conn'])&&isset($connections[$_GET['conn']])){$_SESSION['lanter_connection']=$connections[$_GET['conn']];return$_SESSION['lanter_connection'];}$_SESSION['lanter_connection']=reset($connections);return$_SESSION['lanter_connection'];}private function resolveDelegateMode():?array{$delegate=$this->config->authDelegate();if($delegate===null){return null;}$connection=$delegate();return is_array($connection)?$connection:null;}private function resolveLoginMode():?array{return$_SESSION['lanter_connection']??null;}public function login(array$connection):void{$_SESSION['lanter_connection']=$connection;}}function lanter_render_layout(string$title,string$content,array$tables=[],?string$activeTable=null):void{?><!DOCTYPE html>
