                <tbody>{$body}</tbody>
            </table>
        </div>
        {$pagination}
        HTML;}function lanter_render_row_actions(string$table,string$pkValue):string{$editHref='?action=row_edit&table='.urlencode($table).'&pk='.urlencode($pkValue);$tableAttr=htmlspecialchars($table);$pkAttr=htmlspecialchars($pkValue);return<<<HTML
