                <input type="hidden" name="table" value="{$tableAttr}">
                <input type="hidden" name="pk" value="{$pkAttr}">
                <button class="lanter-action-link lanter-action-danger" type="submit">Excluir</button>
            </form>
        </td>
        HTML;}function lanter_render_pagination(string$table,string$search,int$page,int$lastPage,int$total):string{$link=static function(int$targetPage)use($table,$search):string{$query=['action'=>'dashboard','table'=>$table,'page'=>$targetPage];if($search!==''){$query['q']=$search;}return'?'.http_build_query($query);};$prev=$page>1?'<a class="lanter-page-link" href="'.htmlspecialchars($link($page-1)).'">&larr; Anterior</a>':'<span class="lanter-page-link disabled">&larr; Anterior</span>';$next=$page<$lastPage?'<a class="lanter-page-link" href="'.htmlspecialchars($link($page+1)).'">Próxima &rarr;</a>':'<span class="lanter-page-link disabled">Próxima &rarr;</span>';return<<<HTML
        <div class="lanter-pagination">
