        HTML;lanter_render_layout('Estrutura: '.$activeTable,$content,$tables,$activeTable);}function lanter_action_row_new(Lanter_Config$config,Lanter_Auth$auth,?array$connection):void{$driver=lanter_make_driver($connection);$tables=$driver->listTables();$table=$_GET['table']??'';if(!in_array($table,$tables,true)){lanter_redirect('dashboard');return;}$columns=$driver->describeTable($table);$error=null;$values=$_POST;if($_SERVER['REQUEST_METHOD']==='POST'){$data=lanter_collect_insert_data($columns,$_POST);try{$driver->insertRow($table,$data);lanter_redirect('dashboard',['table'=>$table]);return;}catch(Throwable$e){$error='Não foi possível inserir: '.$e->getMessage();}}$content=lanter_render_row_form($table,$columns,$values,'?action=row_new&table='.urlencode($table),'Novo registro',$error);lanter_render_layout('Novo registro: '.$table,$content,$tables,$table);}function lanter_action_row_edit(Lanter_Config$config,Lanter_Auth$auth,?array$connection):void{$driver=lanter_make_driver($connection);$tables=$driver->listTables();$table=$_GET['table']??'';$pkValue=$_GET['pk']??null;if(!in_array($table,$tables,true)||$pkValue===null){lanter_redirect('dashboard');return;}$columns=$driver->describeTable($table);$primaryKey=lanter_primary_key($columns);if($primaryKey===null){lanter_redirect('dashboard',['table'=>$table]);return;}$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){$data=lanter_collect_update_data($columns,$_POST);try{$driver->updateRow($table,$primaryKey,$_POST['__pk_original']??$pkValue,$data);lanter_redirect('dashboard',['table'=>$table]);return;}catch(Throwable$e){$error='Não foi possível atualizar: '.$e->getMessage();}}$row=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$driver->findRow($table,$primaryKey,$pkValue);if($row===null){lanter_redirect('dashboard',['table'=>$table]);return;}$content=lanter_render_row_form($table,$columns,$row,'?action=row_edit&table='.urlencode($table).'&pk='.urlencode((string)$pkValue),'Editar registro',$error,(string)$pkValue);lanter_render_layout('Editar: '.$table,$content,$tables,$table);}function lanter_collect_insert_data(array$columns,array$input):array{$data=[];foreach($columns as$column){$value=$input[$column['name']]??'';if($column['key']==='PRI'&&$value===''){continue;}$data[$column['name']]=$value===''&&$column['nullable']?null:$value;}return$data;}function lanter_collect_update_data(array$columns,array$input):array{$data=[];foreach($columns as$column){$value=$input[$column['name']]??'';$data[$column['name']]=$value===''&&$column['nullable']?null:$value;}return$data;}function lanter_render_row_form(string$table,array$columns,array$values,string$action,string$title,?string$error,?string$originalPk=null):string{$fields='';foreach($columns as$column){$name=$column['name'];$value=htmlspecialchars((string)($values[$name]??''));$hint=$column['type'].($column['nullable']?', permite nulo':'');$fields.=<<<HTML
